parameters.jsCode:
const items = $input.all();

function clean(value, max = 255) {
  if (value === undefined || value === null) return '';
  return String(value).slice(0, max);
}

const first = items[0]?.json || {};

const executionId = clean($execution.id);
const workflowId = clean($workflow.id);
const workflowName = clean($workflow.name);

const ctx = {
  createdAt: new Date().toISOString(),
  executionKey: `${workflowId}:${executionId}`,
  executionId,
  workflowId,
  workflowName,
  taskId: clean(first.taskId),
  brandId: clean(first.brandId),
  userId: clean(first.userId),
  coreKeyword: clean(first.coreKeyword || first.keywords || first.targetKeyword)
};

try {
  $execution.customData.setAll({
    executionKey: ctx.executionKey,
    taskId: ctx.taskId,
    brandId: ctx.brandId,
    userId: ctx.userId,
    coreKeyword: ctx.coreKeyword
  });
} catch (error) {}

return items.map((item) => ({
  json: {
    ...item.json,
    _ctx: {
      ...(item.json._ctx || {}),
      ...ctx
    }
  },
  binary: item.binary
}));

const original = $('request-parser').first().json;

return [
  {
    json: {
      ...original
    }
  }
];

const item = $input.first();
const comments = item.json?.body?.comments || item.json?.comments || '';

function getField(name) {
  for (const line of comments.split('\n')) {
    const idx = line.indexOf(':');
    if (idx !== -1 && line.substring(0, idx).trim() === name) {
      return line.substring(idx + 1).trim();
    }
  }
  return '';
}

const isGeo = comments.includes('answerIdea') || /(^|\n)\s*question\s*:/i.test(comments);

const lang = getField('targetLanguage').toLowerCase();
const isEnglish = !lang || lang.startsWith('english');

let route;
if (!isGeo && isEnglish)       route = 'seo_en';
else if (isGeo && isEnglish)   route = 'geo_en';
else if (!isGeo && !isEnglish) route = 'seo_lang';
else                           route = 'geo_lang';

return [{ json: { ...item.json, route } }];

const brief = $('Brief Parser').first().json;
const req = $('request-parser').first().json;
const candidates = [
  ['coreKeyword', req.coreKeyword], ['secondaryKeywords', req.secondaryKeywords],
  ['articleType', brief.articleType], ['articleTitle', brief.articleTitle],
  ['contentIdea', brief.contentIdea], ['question', brief.question],
  ['answerIdea', brief.answerIdea], ['writingPreferences', brief.writingPreferences],
  ['ctaRules', brief.ctaRules], ['clientDescription', req.productDescription]
];
const fields = candidates.filter(([n, v]) => v && String(v).trim().length > 0);
return [{ json: {
  fieldNames: fields.map(f => f[0]),
  fieldTexts: fields.map(f => String(f[1])),
  targetSource: brief.targetSource
} }];

const route = $('Route Classifier').first().json.route;
const brief = $('Brief Parser').first().json;
const req = $('request-parser').first().json;
const j = $input.first().json;
const tr = {};
if (j.translations) {
  const names = $('DeepL Prep').first().json.fieldNames;
  if (!Array.isArray(j.translations) || j.translations.length !== names.length) {
    throw new Error(`DeepL returned ${j.translations?.length} translations but expected ${names.length}`);
  }
  names.forEach((n, i) => { tr[n] = j.translations[i].text; });
}
return [{ json: {
  ...brief,
  route,
  isGeo: route.startsWith('geo'),
  isLang: route.endsWith('_lang'),
  coreKeyword: tr.coreKeyword ?? (req.coreKeyword || ''),
  secondaryKeywords: tr.secondaryKeywords ?? (req.secondaryKeywords || ''),
  articleType: tr.articleType ?? brief.articleType,
  articleTitle: tr.articleTitle ?? brief.articleTitle,
  originalTitle: brief.articleTitle,
  contentIdea: tr.contentIdea ?? brief.contentIdea,
  question: tr.question ?? brief.question,
  answerIdea: tr.answerIdea ?? brief.answerIdea,
  writingPreferences: tr.writingPreferences ?? brief.writingPreferences,
  ctaRules: tr.ctaRules ?? brief.ctaRules,
  clientDescription: tr.clientDescription ?? (req.productDescription || '')
} }];

