parameters.jsCode:
const raw = $input.first().json.output || $input.first().json;

let outline;
if (typeof raw === 'string') {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  outline = JSON.parse(cleaned);
} else {
  outline = raw;
}

let formatted = '';

for (const section of outline.sections) {
  formatted += `## ${section.h2_title}\n`;
  formatted += `${section.h2_description}\n\n`;

  if (section.subsections && section.subsections.length > 0) {
    for (const sub of section.subsections) {
      formatted += `### ${sub.h3_title}\n`;
      formatted += `${sub.h3_description}\n\n`;
    }
  }
}

return {
  articleDescription: outline.articleDescription,
  sectionsFormatted: formatted.trim(),
  sectionsRaw: outline.sections
};

