const items = $input.all();
const find = (key) => items.find(i => i.json.output?.[key] !== undefined)?.json.output?.[key] || [];

return [{ json: {
  ingPileups:           find('ingPileups').map(i => i.sentence),
  parallelSeries:       find('parallelSeries').map(i => i.sentence),
  hedging:              find('hedging').map(i => i.sentence),
  negativeParallelisms: find('negativeParallelisms').map(i => i.sentence),
  tailingNegations:     find('tailingNegations').map(i => i.sentence)
}}];

const item = $input.first().json;
const articleText = item.output?.draftedArticle || item.draftedArticle || '';

if (!articleText) {
  throw new Error('No article text found in input. Expected output.draftedArticle or draftedArticle.');
}

const cleanedArticle = articleText
  .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1')
  .replace(/!\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)/g, '')
  .replace(/<(https?:\/\/[^\s>]+)>/g, '')
  .replace(/(?<![[(])(https?:\/\/[^\s)\]]+)/g, '');

return [{
  json: {
    draftedArticle: cleanedArticle
  }
}];

const deeplResponse = $input.first().json;
const prep = $('Translation Prep').first().json;
if (!deeplResponse.translations || !Array.isArray(deeplResponse.translations)) {
  throw new Error(`DeepL response missing translations array. Response: ${JSON.stringify(deeplResponse)}`);
}
if (deeplResponse.translations.length !== prep.fieldNames.length) {
  throw new Error(`DeepL returned ${deeplResponse.translations.length} translations but expected ${prep.fieldNames.length}`);
}

const decodeEntities = (str) =>
  typeof str === 'string'
    ? str
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'")
        .replace(/&#x2F;/g, '/')
    : str;

const translated = {};
prep.fieldNames.forEach((name, idx) => {
  translated[name] = decodeEntities(deeplResponse.translations[idx].text);
});
const finalUserPrompt = translated.userPromptTemplate.replace('{{ARTICLE_PLACEHOLDER}}', translated.article);
return [{
  json: {
    translatedArticle: translated.article,
    translatedUserPrompt: finalUserPrompt,
    translatedSystemPrompt: translated.systemPrompt,
    translatedTavilyQueryDescription: translated.tavilyQueryDescription,
    translatedTavilyToolDescription: translated.tavilyToolDescription
  }
}];

