parameters.jsCode:
const j = $input.first().json;
const article = j.output?.citedArticle || j.output?.draftedArticle || j.citedArticle || j.draftedArticle || '';
if (!article) throw new Error('Article Ready: no article found. Keys: ' + Object.keys(j));
return [{ json: { article } }];

const json = $input.first().json;
const article = json.article || json.linksArticle || json.output?.linksArticle;

if (!article) throw new Error(`Link Extractor: no article found. Keys: ${Object.keys(json)}`);

const regex = /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g;
const links = [];
const seen = new Set();
let m;

while ((m = regex.exec(article)) !== null) {
  if (!seen.has(m[2]) && m[1].trim()) {
    seen.add(m[2]);
    links.push({ url: m[2], claim: m[1] });
  }
}

return links.map(l => ({ json: l }));

const data = $input.first().json.data;
const broken = data
  .filter(i => i.valid === false)
  .map(i => ({ url: i.url, claim: i.claim }));

return [{
  json: {
    hasBroken: broken.length > 0,
    broken
  }
}];

const T = {
  "base": "You are a link replacement specialist. You will receive the full article and a list of broken links (each with a URL and anchor text).\n\n<action_plan>\n**Step 1.** Check the article provided by the user to identify where the anchors with broken links are located exactly.\n**Step 2.** Use Link Finder tool to find a working replacement URL matching the anchor text and context in the corresponding sentence and the paragraph. You MUST call the Link Finder tool for every broken link in the list. Do not attempt to construct or guess replacement URLs from memory. If you do not call Link Finder for each broken link, your output is invalid. Start by calling Link Finder for the first broken link immediately. While doing the replacement, consider this:\n  - You MUST replace only the URL for the corresponding anchor text\n  - A new URL must be from a totally difference resource than the broken one. For example, if the broken link was from Statista resource, than a new link can be from any other source but NEVER from Statista\n  - NEVER change the anchor text\n  - NEVER change any text in the article\n**Step 3.** Provide the final output as a JSON object where the `fixedArticle` field contains the entire article as a single Markdown-formatted string.\n</action_plan>",
  "langSection": "\n\n<query_language>\n- All your queries to the Link Finder tool must be in __F_targetLanguage__ language only because this is the language in which the article is written.\n- You must only pick references for citations that are in __F_targetLanguage__ language.\n- You must NEVER use English sources for references anywhere in the article.\n</query_language>",
  "user": "Replace the following broken links in the article below:\n**Broken links:**",
  "toolDescEn": "Search the web to find a replacement URL for a broken link. Be specific and precise in your search query. Examples: if the anchor text is \"oil spike Iran conflict\", search for \"oil price spike Iran conflict 2026\". Run maximum 2 searches per broken link. Use the best result found and move on. Do not run more than 2 searches for the same broken link.",
  "toolDescLang": "Search the web to find a replacement URL for a broken link. Be specific and precise in your search query. Run maximum 2 searches per broken link. Use the best result found and move on. Do NOT search English because all references must be in __F_targetLanguage__ language only.",
  "queryDesc": "A focused search query of 3-7 words to find authoritative information."
};
const fill = (t, vals) => Object.entries(vals).reduce(
  (s, [k, v]) => s.split('__F_' + k + '__').join(v == null ? '' : String(v)), t);
const brief = $('Brief EN').first().json;
const vals = { targetLanguage: brief.targetLanguage };
let system = T.base;
let toolDesc = T.toolDescEn;
if (brief.isLang) { system += fill(T.langSection, vals); toolDesc = fill(T.toolDescLang, vals); }
const prompts = { system, user: T.user, toolDesc, queryDesc: T.queryDesc };
const fieldNames = Object.keys(prompts);
return [{ json: { prompts, fieldNames, fieldTexts: fieldNames.map(n => prompts[n]), targetSource: brief.targetSource } }];

const prep = $('Prep Fixer').first().json;
const j = $input.first().json;
const dec = s => typeof s === 'string'
  ? s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
     .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x2F;/g, '/')
  : s;
const out = { ...prep.prompts };
if (j.translations) {
  prep.fieldNames.forEach((n, i) => { out[n] = dec(j.translations[i].text); });
}
return [{ json: out }];

